startGuideActivity: "活动是项目中已计划的任务。<br/>你可以创建项目的WBS，<br/>，其层级没有限制",
startGuideAffectation: "资源必须部署到项目才可查看资源项.<br/>部署到项目的资源项对其子项目自动可见.",
startGuideClient: "客户是你为其工作的实体。<br/>它们可以在你的组织内部或外部。",
startGuideContact: "联系人是你在客户实体中所接触的人员。",
startGuideFooter: "以下是主要功能 <br/>熟悉这些功能后，你将能够发现可覆盖项目管理的其他（众多）模块。",
startGuideImputation: "资源在工时表界面按天、按活动录入实际工时。<br/> 重新估算«剩余»工时可根据实际进展更新项目计划。",
startGuideIntro: "这是一份简短教程，帮助你迈出使用 ProjeQtOr 的第一步。<br/> 请按这些步骤配置首批要素。<br/> 随时按 [F1] 打开用户手册以获取更多帮助。<br/> 返回&#34入门指南&#34 菜单即可回到此处。",
startGuideMilestone: "里程碑是项目的关键日期。<br/>它们可以定义输入项（固定里程碑）或交付物（浮动里程碑）。",
startGuidePlanning: "计划提供甘特图视图。<br/>要计划活动就必须为活动分配资源并定义待完成的工时，因为计划以工时驱动。<br/>然后可以定义任务之间的关系（前置链接）以及与里程碑的关系……<br/>随后便可运行计划计算，并考虑资源可用性等全部约束。",
startGuideProject: "项目是ProjectQr的核心。<br/>所有项都连接到某一项目.<br/>访问权限也是在项目层级定义的.",
startGuideResource: "资源是将在任务上工作的人员或机器。<br/>若勾选«是用户»，则该资源（若为人员）将能够连接 ProjeQtOr。",
startGuideTicket: "工单用于跟踪与项目相关的每个突发事项，例如缺陷或各类请求<br/>需要时可以轻松复制为活动，而无需重新录入数据，并保持与原始请求的链接。",
startGuideTitle: "启动指南",
startGuideUser: "用户是可以连接本应用程序的人员。 <br/>他们必须拥有权限配置，以确定对要素的访问权限。",
